// storeSubjects returns the factory of the subjects of Store that calls
// newSubject with the handle of each check.
func storeSubjects[T blob.Store](newSubject func(h *StoreHandle) T) func(h *StoreHandle) blob.Store {
	return func(h *StoreHandle) blob.Store { return newSubject(h) }
}

