// storeOver is a subject of Store whose callables call spend and return
// their zero results. The planted defect of a ceiling passes a spend that
// exceeds the ceiling.
type storeOver struct {
	storeOverEmbedded
	spend func()
}

// Put calls spend and returns its zero results.
func (o storeOver) Put(context.Context, string, io.Reader, blob.PutOptions) (r0 blob.Info, r1 error) {
	o.spend()
	return r0, r1
}

// Get calls spend and returns its zero results.
func (o storeOver) Get(context.Context, string) (r0 io.ReadCloser, r1 blob.Info, r2 error) {
	o.spend()
	return r0, r1, r2
}

